pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testRegression_property() public {
        // Set the sender as owner (the contract's deployer)
        address owner = address(this);
        vm.prank(owner);
        c.approveMax();

        // Retrieve the savings contract address from c
        address savingsAddr = address(c.savings());
        // Retrieve the mAsset token address from c
        address mAssetAddr = address(c.mAsset());

        // Check the allowance that c has granted to the savings contract
        // We need to call IERC20 interface directly on the mAsset token
        // Since we are in test, we can use a minimal interface
        IERC20 mAssetToken = IERC20(mAssetAddr);
        uint256 allowance = mAssetToken.allowance(address(c), savingsAddr);

        // In the reference version, approveMax() sets allowance to type(uint256).max
        // In the bug version, it sets allowance to 0
        assertEq(allowance, type(uint256).max);
    }
}

interface IERC20 {
    function allowance(address owner, address spender) external view returns (uint256);
}

